scwin.setInputBoxInGridHeader = function (gridObj, headerColumnId) {
	var inputBoxObj = {
		div: null,
		getContent: function () {
			this.select = document.createElement("nobr");
			this.select.style.width = "10px";
			this.div = document.createElement("div");


			this.select.id = headerColumnId;
			this.div.appendChild(this.select);


			this.select.innerHTML = "namehoho"

			this.image = document.createElement("img");
			this.image.style.width = "10px";
			this.image.style.height = "10px";

			this.image.setAttribute("src", "http://static.naver.net/green/v2/img/btn_security2_on.gif");
			this.div.appendChild(this.image);


			var _this = this;
			WebSquare.event.addListener(this.image, "onmouseover", function (e) {
				contextGroup.show();
				contextGroup.setPosition(e.clientX, e.clientY + 10);
			}
			);

			WebSquare.event.addListener(this.image, "onmouseout", function (e) {
				contextGroup.hide();
			}
			);

			return this.div;

		}
	}

//inputType="textImage" imageSrc="http://static.naver.net/green/v2/img/btn_security2_on.gif" imageHeight="10" imageWidth="10" viewTypeIconImage="true" viewType="icon"
	var options = {
		"sort": "true"
	}
	gridObj.setHeaderUserObject(headerColumnId, inputBoxObj, options);
};

scwin.gridView1_onsort = function (artSortInfo) {
	console.log("onsort");
};
scwin.gridView1_onheadertextimageclick = function (headerId, headerValue) {
	localStorage.setItem("log", headerId);
	console.log(headerId, headerValue);
	var targetElement = document.querySelector(`[data-header_id=${headerId}]`);

	if (targetElement) {
		var tooltip = document.getElementById($p.id + "contextGroup");
		if (tooltip) {
			if (tooltip.style.display === "none") {
				var rect = targetElement.getBoundingClientRect();
				tooltip.innerHTML = headerValue;
				tooltip.style.top = rect.bottom + 'px';
				tooltip.style.left = rect.left + (rect.width / 2) - (tooltip.offsetWidth / 2) + 'px';
				tooltip.style.display = "flex";
			} else if (tooltip.style.display === "flex") {
				tooltip.style.display = "none";
			}
		}
	}

};
scwin.gridView2_onheadertextimageclick = function (headerId, headerValue) {
	console.log(headerId, headerValue);
};


	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('contextGroup').style.display == 'flex';
	}
	scwin.checkVal2 = function() {
		return localStorage.getItem('log') == 'column3';
	}	
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_column3').getElementsByTagName('img')[0].click()");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "500");			
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
	localStorage.removeItem("log");
